int countUniqueAnagrams(std::vector<std::string> &strs) {
    std::vector<std::string> uniqueAnagrams;
    for (const auto &str : strs) {
        std::string sortedStr = str;
        std::sort(sortedStr.begin(), sortedStr.end());
        bool isUnique = true;
        for (const auto &uniqueStr : uniqueAnagrams) {
