struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

class Solution {
public:
    int getMinimumDifference(TreeNode* root, int k) {
        int result = INT_MAX, prev = -1;
        minimumDifference(root, result, prev, k);
        return result;
    }

    void minimumDifference(TreeNode* node, int& result, int& prev, int k) {
        if (!node) return;
        minimumDifference(node->left, result, prev, k);
        if (prev != -1) {
            result = std::min(result, node->val - prev);
        }
        prev = node->val + k;
        minimumDifference(node->right, result, prev, k);
    }
};
