    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def invert_tree(root):
    if root is None:
        return None
    root.left, root.right = invert_tree(root.right), invert_tree(root.left)
    return root

def find_path(root, target):
    if root is None:
        return False
    if root.val == target:
        return True
    return find_path(root.left, target) or find_path(root.right, target)

def find_common_ancestor(root, p, q):
    if root is None or root.val == p or root.val == q:
        return root
    left = find_common_ancestor(root.left, p, q)
    right = find_common_ancestor(root.right, p, q)
    if left and right:
        return root
    return left if left else right

def find_path_to_common_ancestor(root, p, q):
    common_ancestor = find_common_ancestor(root, p, q)
    path = []
    while common_ancestor:
        path.append(common_ancestor.val)
        common_ancestor = common_ancestor.left if find_path(common_ancestor.left, p) else common_ancestor.right
    return path[::-1]

