    vector<vector<int>> dirs = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
    queue<pair<int, int>> q;
    q.push({start[0], start[1]});
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        if (x == destination[0] && y == destination[1]) return true;
