int shortestPath(vector<vector<int>>& maze, vector<int>& start, vector<int>& destination) {
    int m = maze.size();
    int n = maze[0].size();
    vector<vector<int>> dist(m, vector<int>(n, INT_MAX));
    queue<pair<int, int>> q;
    q.push({start[0], start[1]});
    dist[start[0]][start[1]] = 0;

    while (!q.empty()) {
        int i = q.front().first;
        int j = q.front().second;
        q.pop();

        if (i == destination[0] && j == destination[1]) {
            return dist[i][j];
        }

        if (i > 0 && maze[i - 1][j] == 0 && dist[i - 1][j] == INT_MAX) {
            dist[i - 1][j] = dist[i][j] + 1;
            q.push({i - 1, j});
        }
        if (i < m - 1 && maze[i + 1][j] == 0 && dist[i + 1][j] == INT_MAX) {
            dist[i + 1][j] = dist[i][j] + 1;
            q.push({i + 1, j});
        }
        if (j > 0 && maze[i][j - 1] == 0 && dist[i][j - 1] == INT_MAX) {
            dist[i][j - 1] = dist[i][j] + 1;
            q.push({i, j - 1});
        }
        if (j < n - 1 && maze[i][j + 1] == 0 && dist[i][j + 1] == INT_MAX) {
            dist[i][j + 1] = dist[i][j] + 1;
            q.push({i, j + 1});
        }
    }

    return -1;
}
