vector<vector<int>> colorBorder(vector<vector<int>>& grid, int row, int col, int color) {
    int rows = grid.size();
    int cols = grid[0].size();
    vector<vector<int>> dp(rows, vector<int>(cols, 0));
    vector<vector<int>> result = grid;

    queue<pair<int, int>> q;
    q.push({row, col});
    dp[row][col] = 1;

    while (!q.empty()) {
        int r = q.front().first;
        int c = q.front().second;
        q.pop();

        int count = 0;
        int sum = 0;
        for (int i = -1; i <= 1; ++i) {
            for (int j = -1; j <= 1; ++j) {
                if (i == 0 && j == 0) continue;
                int nr = r + i;
                int nc = c + j;
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == grid[r][c]) {
                    ++count;
                    sum += grid[nr][nc];
                    if (!dp[nr][nc]) {
                        dp[nr][nc] = 1;
                        q.push({nr, nc});
                    }
                }
            }
        }

        if (count != 4) {
            result[r][c] = color;
        }
    }

    return result;
}
