vector<int> count_good_subarrays(vector<vector<int>>& grid, vector<int>& queries) {
    int m = grid.size();
    int n = grid[0].size();
    vector<int> result;
    for (int q : queries) {
        int count = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] <= q) {
                    vector<int> subarray;
                    for (int k = i; k < m; k++) {
                        for (int l = j; l < n; l++) {
                            subarray.push_back(grid[k][l]);
                            if (subarray.size() > q) break;
                            if (subarray.size() == q) count++;
                        }
                        if (subarray.size() > q) break;
                    }
                }
            }
        }
        result.push_back(count);
    }
    return result;
