            }
        }
    }

    int maxPoints = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            maxPoints = std::max(maxPoints, dp[i][j]);
        }
    }

    return maxPoints;
}
