    public int[][] largestConnectedComponent(int[][] land) {
        int m = land.length;
        int n = land[0].length;
        int[][] result = new int[m][n];
        int count = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (land[i][j] == 1) {
                    int size = dfs(land, i, j);
                    for (int k = 0; k < m; k++) {
                        for (int l = 0; l < n; l++) {
                            if (land[k][l] == 1) {
                                result[k][l] = size;
                            }
                        }
                    }
                    count++;
                }
            }
        }
        return result;
    }

    private int dfs(int[][] land, int i, int j) {
        if (i < 0 || i >= land.length || j < 0 || j >= land[0].length || land[i][j] == 0) {
            return 0;
        }
        land[i][j] = 0;
        return 1 + dfs(land, i + 1, j) + dfs(land, i - 1, j) + dfs(land, i, j + 1) + dfs(land, i, j - 1);
    }
