private List<String> helper(String s, HashSet<String> dict, HashMap<String, List<String>> memo) {
    if (memo.containsKey(s)) {
        return memo.get(s);
    }

    List<String> res = new ArrayList<>();
    if (dict.contains(s)) {
        res.add(s);
    }

