public class Solution {
    public String wordBreak(String s, List<String> wordDict) {
        HashSet<String> dict = new HashSet<>(wordDict);
        HashMap<String, String> memo = new HashMap<>();
        return helper(s, dict, memo);
    }

    private String helper(String s, HashSet<String> dict, HashMap<String, String> memo) {
        if (memo.containsKey(s)) {
            return memo.get(s);
        }

        if (dict.contains(s)) {
            memo.put(s, s);
            return s;
        }

        for (int i = 1; i < s.length(); ++i) {
            String prefix = s.substring(0, i);
            if (!dict.contains(prefix)) continue;
            String suffix = s.substring(i);
            String temp = helper(suffix, dict, memo);
            if (temp != null) {
                memo.put(s, prefix + temp);
                return prefix + temp;
            }
        }

        memo.put(s, null);
        return null;
    }
}
