    for (const auto& puzzle : puzzles) {
        int mask = 0;
        for (char c : puzzle) {
            mask |= 1 << (c - 'a');
        }
        int firstChar = 1 << (puzzle[0] - 'a');
        int count = 0;
        for (int subset = mask; subset; subset = (subset - 1) & mask) {
