#include <unordered_map>
#include <queue>
#include <vector>
vector<int> findLeastNumOfUniqueInts(vector<int>& nums, int k) {
    unordered_map<int, int> count;
    for (int n : nums) {
        count[n]++;
    }
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
    for (auto &p : count) {
        pq.push({p.second, p.first});
    }
    while (k > 0) {
        k -= pq.top().first;
        pq.pop();
    }
    vector<int> result;
    while (!pq.empty()) {
        result.push_back(pq.top().second);
        pq.pop();
    }
    return result;
}
