std::string findSubstringWithHash(std::string s, int power, int modulo, int k, int hashValue) {
    std::string result;
    int n = s.length();
    int hash = 0;
    int powerK = 1;

    for (int i = 0; i < k; ++i) {
        hash = (hash * power + (s[i] - 'a')) % modulo;
        powerK = (powerK * power) % modulo;
    }

