bool canSplitIntoKSubstrings(std::string &s, int k) {
    int n = s.size();
    if (n % k != 0) {
        return false;
    }
    int len = n / k;
    for (int i = 0; i < n; i += len) {
        std::string sub = s.substr(i, len);
        if (sub != sub.substr(0, len / 2) + sub.substr(len / 2)) {
            return false;
        }
    }
    return true;
}
