import java.util.*;

public class Solution {
    public int maxBeauty(int[] nums) {
        int n = nums.length;
        int[] left = new int[n];
        int[] right = new int[n];

        left[0] = nums[0];
        for (int i = 1; i < n; i++) {
            left[i] = Math.max(left[i - 1], nums[i]);
        }

        right[n - 1] = nums[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            right[i] = Math.max(right[i + 1], nums[i]);
        }

        int maxBeauty = 0;
        for (int i = 0; i < n; i++) {
            maxBeauty = Math.max(maxBeauty, Math.min(left[i], right[i]));
        }

        return maxBeauty;
    }
}
