import java.util.*;

public class Solution {
    public int maxBeauty(int[] nums, int k) {
        int n = nums.length;
        int[] sortedNums = Arrays.copyOf(nums, n);
        Arrays.sort(sortedNums);

        int count = 0;
        for (int i = 0; i < n; i++) {
            int j = i + 1;
            while (j < n && sortedNums[j] - sortedNums[i] <= k) {
                j++;
            }
            count = Math.max(count, j - i);
        }

        return count;
    }
}
