    sort(tiles.begin(), tiles.end());
    int n = tiles.size();
    int maxTiles = 0;
    int left = 0;
    int right = 0;
    int currentTiles = 0;
    while (right < n) {
        int end = tiles[right][1];
        int start = tiles[right][0];
        if (end - start + 1 <= carpetLen) {
            currentTiles += end - start + 1;
            right++;
        } else {
            int overlap = max(0, start + carpetLen - tiles[left][0]);
            currentTiles += overlap;
            maxTiles = max(maxTiles, currentTiles);
            currentTiles -= tiles[left][1] - tiles[left][0] + 1;
            left++;
        }
    }
    maxTiles = max(maxTiles, currentTiles);
    return maxTiles;
}
