int maxSumPairWithKDifference(vector<int>& nums1, vector<int>& nums2, int k) {
    sort(nums1.begin(), nums1.end());
    sort(nums2.begin(), nums2.end());
    int max_sum = 0;
    int i = 0, j = 0;
    while (i < nums1.size() && j < nums2.size()) {
        if (abs(nums1[i] - nums2[j]) <= k) {
            max_sum = max(max_sum, nums1[i] + nums2[j]);
            if (nums1[i] < nums2[j]) ++i;
            else ++j;
        } else if (nums1[i] < nums2[j]) ++i;
        else ++j;
    }
    return max_sum;
}
