public int findMinOperations(int[] arr) {
    int n = arr.length;
    int[] count = new int[n];
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            if (arr[i] == arr[j]) {
                count[i]++;
                count[j]++;
            }
        }
    }
    int minOps = 0;
    for (int i = 0; i < n; ++i) {
        if (count[i] > 0) {
            minOps += count[i] / 2;
        }
    }
    return minOps;
}
