import java.util.Arrays;

public int maxSumOfSubsequence(int[] nums1, int[] nums2, int k) {
    int n = nums1.length;
    int[][] dp = new int[n + 1][k + 1];
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= k; ++j) {
            dp[i][j] = Math.max(dp[i - 1][j], dp[i - 1][j - 1] + nums1[i - 1] * nums2[i - 1]);
        }
    }
    return dp[n][k];
}
