    public static void main(String[] args) {
        int[] nums = {-2, 0, 1, 3};
        int target = 2;
        System.out.println(findPairs(nums, target)); // Output: 2
    }

    public static int findPairs(int[] nums, int target) {
        if (target < 0) return 0;
        HashSet<Integer> starters = new HashSet<>();
        HashMap<Integer, Integer> occurrences = new HashMap<>();
        for (int num : nums) {
            if (occurrences.containsKey(num + target)) starters.add(num);
            if (occurrences.containsKey(num - target)) starters.add(num - target);
            occurrences.put(num, occurrences.getOrDefault(num, 0) + 1);
        }
        return starters.size();
    }
}
