public int countDisconnectedComponents(int n, int[][] edges) {
    int[] parent = new int[n];
    for (int i = 0; i < n; i++) {
        parent[i] = i;
    }
    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        int pu = findParent(parent, u);
        int pv = findParent(parent, v);
        if (pu != pv) {
            parent[pu] = pv;
        }
    }
    int count = 0;
    for (int i = 0; i < n; i++) {
        if (parent[i] == i) {
            count++;
        }
    }
    return count;
}

private int findParent(int[] parent, int u) {
    if (parent[u] == u) {
        return u;
    }
    return findParent(parent, parent[u]);
}
