public boolean isConnected(int n, int[][] edges, int source, int destination) {
    int[] parent = new int[n];
    for (int i = 0; i < n; i++) {
        parent[i] = i;
    }
    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        int pu = findParent(parent, u);
        int pv = findParent(parent, v);
        if (pu != pv) {
            parent[pu] = pv;
        }
    }
    int ps = findParent(parent, source);
    int pd = findParent(parent, destination);
    return ps == pd;
}
