public int maxNonBannedSum(int[] banned, int n, int maxSum) {
    int sum = 0;
    for (int i = 1; i <= n; i++) {
        if (!isBanned(banned, i)) {
            sum += i;
            if (sum > maxSum) {
                return i - 1;
            }
        }
    }
    return n;
}

private boolean isBanned(int[] banned, int num) {
