    int m = mat.length, n = mat[0].length;
    PriorityQueue<int[]> minHeap = new PriorityQueue<int[]>((a, b) -> a[0] - b[0]);
    minHeap.offer(new int[]{mat[0][0], 0, 0});

    boolean[][] visited = new boolean[m][n];
    visited[0][0] = true;
    int count = 0;

    while (!minHeap.isEmpty()) {
        int[] cur = minHeap.poll();
