        if (count == k) {
            return sum;
        }

        if (row + 1 < m && !visited[row + 1][col]) {
            visited[row + 1][col] = true;
            minHeap.offer(new int[]{sum - mat[row][col] + mat[row + 1][col], row + 1, col});
