int findMinimumSwaps(vector<int>& arr) {
    int n = arr.size();
    vector<int> sorted_arr(arr);
    sort(sorted_arr.begin(), sorted_arr.end());
    vector<int> index_map(n);
    for (int i = 0; i < n; i++) {
        index_map[sorted_arr[i]] = i;
    }
    int swaps = 0;
    for (int i = 0; i < n; i++) {
        while (arr[i] != sorted_arr[i]) {
            int correct_index = index_map[arr[i]];
            swap(arr[i], arr[correct_index]);
            index_map[arr[correct_index]] = correct_index;
            swaps++;
        }
    }
    return swaps;
}
