std::vector<bool> canMakePaliQueries(std::string s, std::vector<std::vector<int>>& queries) {
    std::vector<bool> answer;
    std::vector<int> prefixSum(s.length() + 1);

    for (int i = 0; i < s.length(); ++i) {
        prefixSum[i + 1] = prefixSum[i] ^ (1 << (s[i] - 'a'));
