import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class RomanNumerals {
    public static String intToRoman(int num) {
        List<Pair> romans = Arrays.asList(
            new Pair(1000, "M"), new Pair(900, "CM"), new Pair(500, "D"), 
            new Pair(400, "CD"), new Pair(100, "C"), new Pair(90, "XC"),
            new Pair(50, "L"), new Pair(40, "XL"), new Pair(10, "X"), 
            new Pair(9, "IX"), new Pair(5, "V"), new Pair(4, "IV"),
            new Pair(1, "I")
        );
        StringBuilder roman = new StringBuilder();
        for (Pair p : romans) {
            while (num >= p.num) {
                roman.append(p.symbol);
                num -= p.num;
            }
        }
        return roman.toString();
    }

    public static int romanToInt(String s) {
        List<Pair> romans = Arrays.asList(
            new Pair(1000, "M"), new Pair(900, "CM"), new Pair(500, "D"), 
            new Pair(400, "CD"), new Pair(100, "C"), new Pair(90, "XC"),
            new Pair(50, "L"), new Pair(40, "XL"), new Pair(10, "X"), 
            new Pair(9, "IX"), new Pair(5, "V"), new Pair(4, "IV"),
            new Pair(1, "I")
        );
        int result = 0;
        int i = 0;
        while (i < s.length()) {
            for (Pair p : romans) {
                if (i + p.symbol.length() <= s.length() && s.substring(i, i + p.symbol.length()).equals(p.symbol)) {
                    result += p.num;
                    i += p.symbol.length();
                    break;
                }
            }
        }
        return result;
    }

    private static class Pair {
        final int num;
        final String symbol;

        Pair(int num, String symbol) {
            this.num = num;
            this.symbol = symbol;
        }
    }
}
