import java.util.ArrayList;

public class Solution {
    public List<List<String>> solveNQueens(int n) {
        List<List<String>> result = new ArrayList<>();
        ArrayList<Integer> cols = new ArrayList<>();
        backtrack(n, cols, result);
        return result;
    }

    public void backtrack(int n, ArrayList<Integer> cols, List<List<String>> result) {
        if (cols.size() == n) {
            result.add(generateBoard(cols));
            return;
        }

        for (int i = 0; i < n; i++) {
            if (isSafe(cols, i)) {
                cols.add(i);
                backtrack(n, cols, result);
                cols.remove(cols.size() - 1);
            }
        }
    }

    public boolean isSafe(ArrayList<Integer> cols, int row) {
        int col = cols.size();
        for (int i = 0; i < cols.size(); i++) {
            if (cols.get(i) == row || Math.abs(i - col) == Math.abs(cols.get(i) - row)) {
                return false;
            }
        }
        return true;
    }

    public List<String> generateBoard(ArrayList<Integer> cols) {
        List<String> board = new ArrayList<>();
        for (int i = 0; i < cols.size(); i++) {
            StringBuilder row = new StringBuilder();
            for (int j = 0; j < cols.size(); j++) {
                if (j == cols.get(i)) {
                    row.append('Q');
                } else {
                    row.append('.');
                }
            }
            board.add(row.toString());
        }
        return board;
    }
}
