    int left = 2, right = x / 2, mid, square;
    while (left <= right) {
        mid = left + (right - left) / 2;
        square = mid * mid;
        if (square == x) return mid;
        if (square > x) right = mid - 1;
        else left = mid + 1;
    }
    return right;
}
