int largestRectangleArea(vector<int>& heights) {
    if (heights.empty()) return 0;

    int n = heights.size();
    vector<int> left(n, 0);
    vector<int> right(n, n - 1);
    stack<int> s;

    for (int i = 0; i < n; ++i) {
        while (!s.empty() && heights[s.top()] >= heights[i]) {
            s.pop();
