public boolean containsNearbyAlmostDuplicate(int[] nums, int indexDiff, int valueDiff) {
    if (indexDiff < 1 || valueDiff < 0) {
        return false;
    }
    Map<Long, Long> map = new HashMap<>();
    long bucketSize = (long) valueDiff + 1;
    for (int i = 0; i < nums.length; i++) {
        long bucket = getBucket(nums[i], bucketSize);
        if (map.containsKey(bucket)) {
            return true;
        }
        if (map.containsKey(bucket - 1) && Math.abs(nums[i] - map.get(bucket - 1)) < bucketSize) {
            return true;
        }
        if (map.containsKey(bucket + 1) && Math.abs(nums[i] - map.get(bucket + 1)) < bucketSize) {
            return true;
        }
        map.put(bucket, (long) nums[i]);
        if (i >= indexDiff) {
            map.remove(getBucket(nums[i - indexDiff], bucketSize));
        }
    }
    return false;
}

private long getBucket(long num, long bucketSize) {
    return num < 0 ? (num + 1) / bucketSize - 1 : num / bucketSize;
}
