struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
};

int findKthMinimumValue(TreeNode* root, int k) {
    if (!root || k <= 0) return -1;
    int count = 0;
    int result = -1;
    std::function<void(TreeNode*)> dfs = [&](TreeNode* node) {
        if (!node) return;
        dfs(node->left);
        if (++count == k) {
            result = node->val;
            return;
        }
        dfs(node->right);
    };
    dfs(root);
    return result;
}
