#include <vector>
#include <algorithm>

int minMeetingRooms(std::vector<std::vector<int>>& intervals) {
    if (intervals.empty()) return 0;

    std::vector<int> startTimes, endTimes;
    for (const auto& interval : intervals) {
        startTimes.push_back(interval[0]);
        endTimes.push_back(interval[1]);
    }

    std::sort(startTimes.begin(), startTimes.end());
    std::sort(endTimes.begin(), endTimes.end());

    int rooms = 0, count = 0;
    int i = 0, j = 0;
    while (i < startTimes.size() && j < endTimes.size()) {
        if (startTimes[i] < endTimes[j]) {
            count++;
            i++;
        } else {
            count--;
            j++;
        }
        rooms = std::max(rooms, count);
    }

    return rooms;
}
