        self.val = val
        self.left = left
        self.right = right

def count_nodes(root):
    if not root:
        return 0
    ld = rd = 0
    l = r = root

    while l:
        l = l.left
        ld += 1

    while r:
        r = r.right
        rd += 1

    if ld == rd:
        return (1 << ld) - 1
    return 1 + count_nodes(root.left) + count_nodes(root.right)

def find_closest_value(root, target):
    if not root:
        return None
    closest = root.val
    while root:
        if abs(root.val - target) < abs(closest - target):
            closest = root.val
        if target < root.val:
            root = root.left
        else:
            root = root.right
    return closest

