    if (root == null) {
        return 0;
    }

    int longestSeq = 0;

    Stack<TreeNode> stack = new Stack<>();
    stack.push(root);

    while (!stack.isEmpty()) {
        TreeNode node = stack.pop();

        if (node.left != null) {
            stack.push(node.left);
        }

        if (node.right != null) {
            stack.push(node.right);
        }

        if (node.val + 1 == node.left.val || node.val - 1 == node.right.val) {
            longestSeq++;
        }
    }

    return longestSeq;
}
