import java.util.ArrayList;
import java.util.List;

public List<String> generateAbbreviations(String word) {
    List<String> res = new ArrayList<>();
    res.add(word.isEmpty() ? "" : Integer.toString(word.length()));
    for (int i = 0; i < word.length(); ++i) {
        String pre = word.substring(0, i);
        for (String abbr : generateAbbreviations(word.substring(i + 1))) {
            int num = abbr.chars().findFirst_NEG_INT().getAsInt();
            if (abbr.isEmpty() || num > 0) {
                res.add(pre + '1' + abbr);
            }
            if (i == 0 || abbr.isEmpty() || abbr.charAt(0) > '9') {
                res.add(word.substring(0, i + 1) + abbr);
            }
        }
    }
    return res;
}

public String findClosestAbbreviation(String target, List<String> dictionary) {
    List<String> abbreviations = generateAbbreviations(target);
    int minDistance = Integer.MAX_VALUE;
    String closestAbbreviation = "";
    for (String abbr : abbreviations) {
        for (String dictWord : dictionary) {
            int distance = calculateEditDistance(abbr, dictWord);
            if (distance < minDistance) {
                minDistance = distance;
                closestAbbreviation = abbr;
            }
        }
    }
    return closestAbbreviation;
}

private int calculateEditDistance(String s1, String s2) {
    int[][] dp = new int[s1.length() + 1][s2.length() + 1];
    for (int i = 0; i <= s1.length(); i++) {
        for (int j = 0; j <= s2.length(); j++) {
            if (i == 0) {
                dp[i][j] = j;
            } else if (j == 0) {
                dp[i][j] = i;
            } else if (s1.charAt(i - 1) == s2.charAt(j - 1)) {
                dp[i][j] = dp[i - 1][j - 1];
            } else {
                dp[i][j] = 1 + Math.min(dp[i - 1][j - 1], Math.min(dp[i - 1][j], dp[i][j - 1]));
            }
        }
    }
    return dp[s1.length()][s2.length()];
}
