#include <iostream>

int calculateTotalTime(const std::vector<int>& timeSeries, int duration) {
    int totalTime = 0;
    int lastEffectEnd = 0;

    for (int time : timeSeries) {
        if (time > lastEffectEnd) {
            totalTime += duration;
        } else {
            totalTime += time + duration - lastEffectEnd;
        }
        lastEffectEnd = time + duration;
    }

    return totalTime;
}

int main() {
    std::vector<int> timeSeries = {1, 4};
    int duration = 2;
    int result = calculateTotalTime(timeSeries, duration);
    std::cout << "Total time: " << result << std::endl; // Output: 4
    return 0;
}
