    int n = s.length();
    if (n == 0) return 0;

    int maxLength = 1;

    for (int i = 0; i < n; ++i) {
        int l = i, r = i;

        while (r < n - 1 && s.charAt(r) == s.charAt(r + 1))
            r++;
        i = r;

        while (l > 0 && r < n - 1 && s.charAt(l - 1) == s.charAt(r + 1)) {
            l--;
            r++;
        }

        int length = r - l + 1;
        if (length > maxLength) {
            maxLength = length;
        }
    }

    return maxLength;
}
