int findLUSlength(vector<string>& strs) {
    int n = strs.size();
    int max_len = -1;
    for (int i = 0; i < n; i++) {
        bool is_unique = true;
        for (int j = 0; j < n; j++) {
            if (i != j && strs[i] == strs[j]) {
                is_unique = false;
                break;
            }
        }
        if (is_unique) {
            max_len = max(max_len, (int)strs[i].length());
        }
    }
    return max_len;
}
