                if (new_days > dp[next_city][day + 1]) {
                    dp[next_city][day + 1] = new_days;
                    q.push({next_city, day + 1});
                }
            }
        }
    }
    int max_days = 0;
    for (int i = 0; i < n; ++i) {
        max_days = max(max_days, dp[i][k - 1]);
    }
    return max_days;
