std::vector<std::string> topKFrequentWords(std::vector<std::string>& words, int k) {
    std::vector<std::string> result;
    std::vector<int> word_count(10000, 0);
    for (const auto& word : words) {
        word_count[word.length()]++;
    }
    std::vector<std::pair<int, std::string>> word_freq;
    for (int i = 0; i < word_count.size(); ++i) {
        if (word_count[i] > 0) {
            word_freq.push_back({word_count[i], std::string(i, 'a')});
        }
    }
    std::sort(word_freq.begin(), word_freq.end(), [](const auto& a, const auto& b) {
        return a.first > b.first || (a.first == b.first && a.second < b.second);
    });
    for (int i = 0; i < k && i < word_freq.size(); ++i) {
        result.push_back(word_freq[i].second);
    }
    return result;
}
